let
    Source = fxRead("SELECT c.production_id, c.material_id, c.required_kg, c.extra_waste_kg, c.consumed_kg, c.issued_material_value_eur, c.weighted_average_unit_cost_eur, c.issued_purchase_material_value_eur, c.issued_inbound_freight_eur, c.weighted_average_purchase_unit_cost_eur, c.weighted_average_inbound_freight_unit_cost_eur, c.month_id, c.product_id, c.product_name, c.material_name, p.line_id FROM manufacturing_v2.bi_material_consumption c JOIN manufacturing_v2.products p ON p.product_id=c.product_id"),
    Typed = Table.TransformColumnTypes(Source, {{"line_id", type text}, {"month_id", type date}, {"product_id", type text}, {"consumed_kg", type number}, {"material_id", type text}, {"required_kg", type number}, {"product_name", type text}, {"material_name", type text}, {"production_id", type text}, {"extra_waste_kg", type number}, {"issued_material_value_eur", Currency.Type}, {"issued_inbound_freight_eur", Currency.Type}, {"weighted_average_unit_cost_eur", type number}, {"issued_purchase_material_value_eur", Currency.Type}, {"weighted_average_purchase_unit_cost_eur", type number}, {"weighted_average_inbound_freight_unit_cost_eur", type number}}, "en-US")
in Typed
